mapper.select:
select
from gateway_permission gp left join (select dict_name, dict_val from gateway_dict where dict_type_id = 1) gd on gp.open = CAST(gd.dict_val AS smallint)
${ew.customSqlSegment}
where 1 = 1
and group_id in
#{ids}

select t.group_name, t.group_create_time, t.id, t.group_id, t.url_name, t.url, t.open, t.description, t.fixed, t.create_time from ( select gpg.group_name, gpg.create_time AS group_create_time, gp.*, row_number() over (partition by gp.group_id order by gp.create_time desc) as rn from gateway_permission_group gpg right join gateway_permission gp ON gpg.id = gp.group_id left join (select dict_name, dict_val from gateway_dict where dict_type_id = 1) gd on gp.open = CAST(gd.dict_val AS smallint)
${ew.customSqlSegment}
where 1 = 1
) t where t.rn = 1 or t.group_id = 0 order by t.group_id = 0, coalesce(t.group_id, 0), t.create_time desc
